import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

public class Main {
    static int gcd(int a, int b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }

    static long modPow(long a, long n, long m) {
        if (n == 0) return 1;
        if (n % 2 == 0) return modPow((a * a) % m, n / 2, m);
        return (a * modPow(a, n - 1, m)) % m;
    }

    static int[] extendedEuclid(int a, int b) {
        if (b == 0) return new int[]{1, 0};
        else {
            int[] res = extendedEuclid(b, a % b);
            int x = res[0];
            int y = res[1];
            return new int[]{y, x - (a / b) * y};
        }
    }

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        StringBuilder sb = new StringBuilder();
        while (sc.hasNext()) {
            sb.append(sc.next()).append(" ");
        }
        String input = sb.toString().trim();
        String[] inp = input.split("\\s+");

        int n = Integer.parseInt(inp[0]);
        int k = Integer.parseInt(inp[1]);
        String s = inp[2];
        String t = inp[3];

        if (t.charAt(0) == t.charAt(1)) {
            int count = 0;
            for (char c : s.toCharArray()) {
                if (c == t.charAt(0)) count++;
            }
            int x = Math.min(count + k, n);
            System.out.println(x * (x - 1) / 2);
            return;
        }

        int NEG_INF = -100000;
        int[][][] f = new int[n + 1][k + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                Arrays.fill(f[i][j], NEG_INF);
            }
        }
        f[0][0][0] = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= k; j++) {
                for (int cnt0 = 0; cnt0 <= i; cnt0++) {
                    if (f[i][j][cnt0] < 0) continue;
                    int e0 = (s.charAt(i) == t.charAt(0)) ? 1 : 0;
                    int e1 = (s.charAt(i) == t.charAt(1)) ? 1 : 0;

                    if (cnt0 + e0 <= n) {
                        f[i + 1][j][cnt0 + e0] = Math.max(f[i + 1][j][cnt0 + e0], f[i][j][cnt0] + e1 * cnt0);
                    }
                    if (j + 1 <= k) {
                        if (cnt0 + 1 <= n) {
                            f[i + 1][j + 1][cnt0 + 1] = Math.max(f[i + 1][j + 1][cnt0 + 1], f[i][j][cnt0]);
                        }
                        f[i + 1][j + 1][cnt0] = Math.max(f[i + 1][j + 1][cnt0], f[i][j][cnt0] + cnt0);
                    }
                }
            }
        }

        int maxVal = NEG_INF;
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= n; j++) {
                if (f[n][i][j] > maxVal) {
                    maxVal = f[n][i][j];
                }
            }
        }
        System.out.println(maxVal);
    }
}

